function branchArea(r){const st=stores.find(x=>x.id===r.branchStoreId);return st?st.area:'Another branch';}
function profileSizes(p){return (p.gender?genderLabels[p.gender]+' · ':'')+['topwear','bottomwear','footwear'].map(k=>categoryNames[k]+' '+(p.sizes[k]||'Not set')).join(' · ');}
function requestSummary(r){if(!r)return 'No request selected.';return storeName(stores.find(s=>s.id===r.storeId))+'\n'+products.find(p=>p.id===r.productId).name+' · '+r.size;}
function reservationSummary(r){if(!r)return 'No reservation selected.';const p=products.find(p=>p.id===r.productId);return storeName(stores.find(s=>s.id===r.storeId))+'\n'+p.name+' · '+r.size+'\n'+money(p.price)+' · Pay at store';}
function remaining(r){const seconds=Math.max(0,Math.floor((r.expiresAt-Date.now())/1000));return Math.floor(seconds/60)+' min '+String(seconds%60).padStart(2,'0')+' sec remaining';}
function sendRequest(){if(!navigator.onLine)throw Error('Reconnect before sending a request.');const r=createRequest(state,{kind:ui.requestType,productId:product().id,size:sizeFor(product()),message:ui.message,name:ui.contactName,phone:ui.phone});state.activeRequestId=r.id;ui.message='';go('request-sent');}
function replyToRequest(scenario){if(!navigator.onLine)throw Error('Reconnect to preview a reply.');if(activeRequest()?.status===scenario)throw Error('That demo reply is already shown.');demoReply(state,state.activeRequestId,scenario);ui.message='';persist();render(false);}
function openDirections(st){const query=encodeURIComponent(st.brand+' '+st.area+' Goa');window.open('https://www.google.com/maps/search/?api=1&query='+query,'_blank','noopener,noreferrer');}
function useLocation(){if(!navigator.geolocation){go('location-off');return;}toast('Checking your location…');navigator.geolocation.getCurrentPosition(pos=>{state.location={name:'Your current location',lat:pos.coords.latitude,lng:pos.coords.longitude};resetMapView();state.onboarded=true;go('browse');},()=>go('location-off'),{enableHighAccuracy:false,timeout:10000,maximumAge:60000});}
